contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public test function
    function run(uint256 deposit) public payable {
        require(address(this).balance >= deposit);
        // deposit Ether into c on behalf of this contract
        c.fallback{value: deposit}();
        // read recorded balance in c for this contract (public getter)
        uint256 beforeBalance = c.balances(address(this));
        // also read contract's Ether balance
        uint256 cBalanceBefore = address(c).balance;
        bool reverted;
        // attempt withdraw and record if it reverted
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance = c.balances(address(this));
        uint256 cBalanceAfter = address(c).balance;
        // General rule: if withdraw did not revert, then the stored balance for this contract became zero
        // and the contract's Ether balance decreased by at least the previous stored amount (no unexpected creation of Ether).
        assert(reverted || (afterBalance == 0 && cBalanceAfter + beforeBalance <= cBalanceBefore));
    }
    // accept refunds if any
    receive() external payable {}
}

