contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: depositAmount to send to fallback to set up a nonzero balance, and withdrawGaslessFlag unused but demonstrates param usage
    function run(uint256 depositAmount, bool withdrawShouldSucceed) public payable {
        require(address(this).balance >= depositAmount);
        // ensure starting observation: balance of this address with contract before any action
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeRecorded = c.balances(address(this));
        // make a deposit to increase recorded balance
        if (depositAmount > 0) {
            c.f{value: depositAmount}();
        }
        uint256 afterDepositRecorded = c.balances(address(this));
        uint256 expectedRecorded = beforeRecorded + depositAmount;
        // recorded balance should have increased by the deposit amount
        assert(afterDepositRecorded == expectedRecorded);
        // capture contract balance before withdraw
        uint256 balanceBeforeWithdraw = address(c).balance;
        // attempt withdraw and detect revert
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfterWithdraw = address(c).balance;
        uint256 recordedAfter = c.balances(address(this));
        // General rule: if withdraw succeeded, recorded balance becomes zero and contract balance decreased by previous recorded amount;
        // if it reverted, recorded balance and contract balance remain unchanged.
        if (!reverted) {
            // contract must have sent the recorded amount and set recorded to zero
            // check recorded is zero and contract balance decreased by the recorded amount before withdraw
            assert(recordedAfter == 0);
            assert(balanceBeforeWithdraw == balanceAfterWithdraw + expectedRecorded);
        } else {
            // on revert nothing should have changed
            assert(recordedAfter == expectedRecorded);
            assert(balanceBeforeWithdraw == balanceAfterWithdraw);
        }
    }
    receive() external payable {}
}

