contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: deposit some Ether into c (amount) and then call withdraw;
    // assert that if withdraw did not revert, c.balances(address(this)) is zero and c's balance decreased accordingly.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for deposit");

        // record before-values
        uint256 beforeStored = c.balances(address(this));
        uint256 beforeBalanceC = address(c).balance;

        // deposit Ether into c by calling its fallback
        if (amount > 0) {
            // send Ether to c's fallback which increments balances[msg.sender]
            (bool sent, ) = address(c).call{value: amount}("");
            require(sent, "deposit failed");
        }

        // after deposit, read stored balance
        uint256 afterStored = c.balances(address(this));
        uint256 afterBalanceC = address(c).balance;

        // The deposit should have increased both stored and contract balance by the same amount
        // (this is a useful relation but not the final assertion)
        // Now attempt withdraw and capture whether it reverted
        bool didRevert;
        try c.withdraw() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // read post-withdraw values
        uint256 finalStored = c.balances(address(this));
        uint256 finalBalanceC = address(c).balance;

        // General property to assert:
        // If withdraw succeeded (didRevert == false) then the contract's stored balance for this test
        // address must be zero and the contract's Ether balance must have decreased by at least the
        // amount that was recorded just before withdraw (i.e., after deposit). If withdraw reverted,
        // we make no claim about balances.
        assert(didRevert || (finalStored == 0 && beforeBalanceC + amount == afterBalanceC && afterBalanceC >= finalBalanceC && (afterBalanceC - finalBalanceC) >= afterStored));
    }

    // receive to accept refunds if any
    receive() external payable {}
}

