    constructor(C _c) { c = _c; }

    // We accept two parameters: an amount to deposit (in wei) and a flag whether to attempt withdraw afterwards.
    // The test sends 'depositAmount' wei to c via its fallback, then attempts withdraw and asserts the general invariant.
    function run(uint256 depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // Record contract c balance before deposit
        uint256 beforeC = address(c).balance;

        // Deposit funds to c by invoking its fallback (payable) from this contract
        // This increases both balances[msg.sender] inside c and address(c).balance
        c.f{value: depositAmount}();

        // Read the recorded balance for this contract's address in c
        uint256 recorded = c.balances(address(this));

        // It must have increased by exactly depositAmount
        // (we will check this as part of the final assertion)

        bool withdrew = false;
        bool reverted = false;
        uint256 afterCBeforeWithdraw = address(c).balance;

        if (doWithdraw) {
            // Attempt withdraw and capture whether it reverts
            try c.withdraw() {
                withdrew = true;
            } catch {
                reverted = true;
            }
        }

        uint256 afterC = address(c).balance;
        uint256 recordedAfter = c.balances(address(this));

        // General rule to assert for all inputs:
        // 1) The recorded balance immediately after deposit equals previous recorded + depositAmount.
        // 2) If withdraw succeeded (not reverted and doWithdraw true), then recordedAfter == 0 and c's balance decreased by at most 'recorded' (i.e., it paid out exactly recorded or less if call failed — but success implies it paid recorded and balances set to 0).
        // 3) If withdraw reverted or not attempted, recordedAfter equals recorded.
        // We combine these into one assert expressing the intended properties.

        assert(
            // deposit effect: recorded equals depositAmount (since starting balances for fresh c and this test are zero)
            recorded == depositAmount
            && (
                // Case: withdraw was attempted and succeeded
                (doWithdraw && withdrew && !reverted && recordedAfter == 0 && beforeC + depositAmount >= afterC && beforeC + depositAmount - afterC == depositAmount)
                ||
                // Case: withdraw attempted but reverted -> balances unchanged and contract balance unchanged
                (doWithdraw && reverted && recordedAfter == recorded && afterC == afterCBeforeWithdraw)
                ||
                // Case: withdraw not attempted -> balances remain as recorded and contract balance equals before+deposit
                (!doWithdraw && recordedAfter == recorded && afterC == afterCBeforeWithdraw)
            )
        );
    }

    // Allow the test contract to receive Ether so it can deposit
    receive() external payable {}
}

